// F37 – gemensam testkörare för luminusloom.net.
// Kör varje tests/*.test.cjs från repots rot och skriver en rad per test: OK eller FEL, antal kontroller och tid.
// Avslutar med kod 1 om något test fallerar, annars 0. Inga beroenden, bara Node.
// Används i läskontrollen F35: `node tests/kor-alla.cjs` (eller `node tests/kor-alla.cjs --json`).
// AI-skapat (B-051). Generated by AI, Directed by MS.
const fs = require('fs');
const path = require('path');
const { spawnSync } = require('child_process');

const rot = path.resolve(__dirname, '..');
const json = process.argv.includes('--json');
const filer = fs.readdirSync(__dirname).filter((f) => f.endsWith('.test.cjs')).sort();

// Den mest läsbara felraden: första raden som nämner Error, annars första raden, annars timeout.
function forstaFel(k) {
  if (k.error) return k.error.code === 'ETIMEDOUT' ? 'timeout efter 30 s' : String(k.error.message);
  const rader = (k.stderr || '').trim().split('\n').filter(Boolean);
  return rader.find((r) => /Error/.test(r)) || rader[0] || `utgångskod ${k.status}`;
}

const resultat = filer.map((fil) => {
  const start = Date.now();
  const k = spawnSync(process.execPath, [path.join('tests', fil)], { cwd: rot, encoding: 'utf8', timeout: 30000 });
  let kontroller = null;
  let fallerade = [];
  const sista = (k.stdout || '').trim().split('\n').pop();
  try {
    const obj = JSON.parse(sista);
    const nycklar = Object.keys(obj).filter((n) => n !== 'ok');
    kontroller = nycklar.length;
    fallerade = nycklar.filter((n) => obj[n] === false);
  } catch (_) { /* testet skriver inte JSON; då räknas bara utgångskoden */ }
  return { fil, ok: k.status === 0, kontroller, fallerade, ms: Date.now() - start, fel: k.status === 0 ? '' : forstaFel(k) };
});

// Inga tester är inte ett fel (main har ännu inga sidtester), men det sägs tydligt.
const alla = resultat.every((r) => r.ok);
if (json) {
  console.log(JSON.stringify({ antal: resultat.length, ok: alla, resultat }));
} else {
  if (resultat.length === 0) console.log('Inga tester hittades i tests/ (*.test.cjs).');
  for (const r of resultat) {
    const antal = r.kontroller === null ? '' : ` ${r.kontroller - r.fallerade.length}/${r.kontroller}`;
    const extra = r.ok ? '' : `  fallerade: ${r.fallerade.join(', ') || r.fel || 'okänt'}`;
    console.log(`${r.ok ? 'OK ' : 'FEL'} ${r.fil}${antal} (${r.ms} ms)${extra}`);
  }
  if (resultat.length > 0) console.log(`${alla ? 'Alla gröna' : 'Minst ett test är rött'}: ${resultat.filter((r) => r.ok).length} av ${resultat.length}.`);
}
process.exit(alla ? 0 : 1);
